6	/**
7	 * Entry step for {@code POST /api/owners}. When the request carries an
8	 * {@code Idempotency-Key} already seen, replay the originally created owner; otherwise
9	 * run the normal create pipeline.
10	 */
11	public class CheckIdempotencyKey {
12	
13	    @FunctionalInterface
14	    public interface CreateFlow {
15	        void create();
16	    }
17	
18	    @FunctionalInterface
19	    public interface ReplayFlow {
20	        void replay(Integer ownerId);
21	    }
22	
23	    public void service(@RequestHeader(name = "Idempotency-Key", required = false) String key,
24	            IdempotencyStore idempotencyStore, @Flow("create") CreateFlow create,
25	            @Flow("replay") ReplayFlow replay) {
26	        Integer existing = key == null ? null : idempotencyStore.find(key);
27	        if (existing != null) {
28	            replay.replay(existing);
29	        }
30	        else {
31	            create.create();
32	        }
33	    }
34	}
