3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns the owner's unified {@code memberId} as {@code <REGION><FY><HASH8><CHK>}: the
12	 * region code derived from the postcode (see {@link Locality}), the two-digit fiscal year,
13	 * the first eight upper-case hex characters of the SHA-256 of the normalised telephone
14	 * concatenated with the last name (the same HASH8 as the region-and-hash identity), then a
15	 * single Luhn check digit ({@link CheckDigit}) over the digits of {@code <REGION><FY><HASH8>}.
16	 * No sequence numbers are used, so the id is a stable function of the owner's identity.
17	 * The value is stored in the owner's customer-code column and de-duplicated downstream.
18	 */
19	public class AssignOwnerCustomerCode {
20	
21	    public void service(@Val Owner owner) {
22	        String base = (Locality.of(owner) + "V2")
23	                + String.format("%02d", FiscalYear.of(owner.getRegistrationDate()) % 100)
24	                + hash8(owner.getTelephone() + owner.getLastName());
25	        owner.setCustomerCode(base + CheckDigit.of(base));
26	    }
27	
28	    private static String hash8(String seed) {
29	        try {
30	            byte[] digest = MessageDigest.getInstance("SHA-256")
31	                    .digest(seed.getBytes(StandardCharsets.UTF_8));
32	            StringBuilder sb = new StringBuilder(8);
33	            for (int i = 0; i < 4; i++) {
34	                sb.append(String.format("%02X", digest[i]));
35	            }
36	            return sb.toString();
37	        }
38	        catch (NoSuchAlgorithmException e) {
39	            throw new IllegalStateException(e);
40	        }
41	    }
42	}
