30	        Integer possibleDuplicateOf = PossibleDuplicate.of(owner, ownerRepository);
31	        dto.setPossibleDuplicate(possibleDuplicateOf != null);
32	        dto.setPossibleDuplicateOf(possibleDuplicateOf);
