3	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
4	import org.springframework.samples.petclinic.rest.escalation.AddressRequiredException;
5	
6	/**
7	 * Resolves the request's address into its normalized, stored form. The structured fields
8	 * are preferred: when {@code addressLine1} is non-blank the stored {@code address} becomes
9	 * the normalized line 1 with the normalized {@code addressLine2} appended after a single
10	 * space (when present). Otherwise the flat {@code address} is normalized as before, which
11	 * rejects a request that supplies neither form.
12	 */
13	final class AddressForm {
14	
15	    private AddressForm() {
16	    }
17	
18	    static void apply(OwnerFieldsDto request) throws AddressRequiredException {
19	        String line1 = request.getAddressLine1();
20	        if (line1 == null || line1.isBlank()) {
21	            request.setAddress(Address.normalize(request.getAddress()));
22	            return;
23	        }
24	        String normalizedLine1 = Address.normalize(line1);
25	        String line2 = request.getAddressLine2();
26	        boolean hasLine2 = line2 != null && !line2.isBlank();
27	        String normalizedLine2 = hasLine2 ? Address.normalize(line2) : null;
28	        request.setAddressLine1(normalizedLine1);
29	        request.setAddressLine2(normalizedLine2);
30	        request.setAddress(hasLine2 ? normalizedLine1 + " " + normalizedLine2 : normalizedLine1);
31	    }
32	}
