3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives an owner's identity key — the single value all duplicate detection is based on.
12	 * It is the SHA-256 hex digest over the normalized telephone, the lower-cased email and the
13	 * {@link Soundex} of the last name, joined by '|'. Two owners are duplicates only when their
14	 * whole keys match; a shared telephone, email or surname alone is not enough.
15	 */
16	public final class IdentityKey {
17	
18	    private IdentityKey() {
19	    }
20	
21	    public static String of(Owner owner) {
22	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
23	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
24	        String seed = "V2|" + telephone + "|" + email + "|" + Soundex.of(owner.getLastName());
25	        try {
26	            byte[] digest = MessageDigest.getInstance("SHA-256")
27	                    .digest(seed.getBytes(StandardCharsets.UTF_8));
28	            StringBuilder sb = new StringBuilder(64);
29	            for (byte b : digest) {
30	                sb.append(String.format("%02x", b));
31	            }
32	            return sb.toString();
33	        }
34	        catch (NoSuchAlgorithmException e) {
35	            throw new IllegalStateException(e);
36	        }
37	    }
38	}
