6	
7	/**
8	 * Rolls a date forward to a business day: weekends and listed public holidays advance to
9	 * the next non-holiday weekday; any other weekday is returned unchanged.
10	 */
11	final class BusinessDay {
12	
13	    private static final Set<LocalDate> HOLIDAYS = Set.of(
14	            LocalDate.of(2026, 1, 1),
15	            LocalDate.of(2026, 1, 26),
16	            LocalDate.of(2026, 4, 25),
17	            LocalDate.of(2026, 12, 25),
18	            LocalDate.of(2026, 12, 28));
19	
20	    private BusinessDay() {
21	    }
22	
23	    static LocalDate rollForward(LocalDate date) {
24	        while (isNonBusinessDay(date)) {
25	            date = date.plusDays(1);
26	        }
27	        return date;
