8	 * one's {@link Soundex} of the last name and postcode but whose {@link IdentityKey} differs — a
9	 * soft match that is not a hard identity duplicate (a differing telephone is enough to make the
10	 * keys differ). Returns the earliest such owner's id, or {@code null} when there is none.
11	 */
12	public final class PossibleDuplicate {
13	
14	    private PossibleDuplicate() {
15	    }
16	
17	    public static Integer of(Owner owner, OwnerRepository ownerRepository) {
18	        String postcode = owner.getPostcode();
19	        if (postcode == null || postcode.isBlank()) {
20	            return null;
21	        }
22	        String soundex = Soundex.of(owner.getLastName());
23	        String identityKey = IdentityKey.of(owner);
24	        return ownerRepository.findAll().stream()
25	                .filter(other -> other.getId() != null && !other.getId().equals(owner.getId()))
26	                .filter(other -> !identityKey.equals(IdentityKey.of(other)))
27	                .filter(other -> postcode.equals(other.getPostcode()))
28	                .filter(other -> soundex.equals(Soundex.of(other.getLastName())))
29	                .map(Owner::getId)
30	                .min(Integer::compareTo)
31	                .orElse(null);
32	    }
